const body = $input.first().json.body ?? $input.first().json;
const alarm = body?.alarm && typeof body.alarm === 'object' ? body.alarm : {};
const events = Array.isArray(body?.events) ? body.events : [];
const first = events[0] && typeof events[0] === 'object' ? events[0] : {};
const scope = first.scope && typeof first.scope === 'object' ? first.scope : {};

const config = {
  // Edit these for your site. Broader parameterization is deferred (NNR-7).
  gatewayUrl: 'https://unifi.example.com',
  site: 'default',
  // Preferred: UniFi OS API key (X-API-KEY). Leave empty to use UniFi login credential.
  apiKey: '',
  // Incoming Slack webhook URL (same delivery path as unifi-notifi).
  slackWebhookUrl: 'https://hooks.slack.com/services/CHANGE/ME/HERE',
  lookbackMinutes: 15,
  // Lets the rest of a burst land in the threat log before it is read.
  settleSeconds: 45,
  // When false, UniFi HTTPS calls skip certificate verification (self-signed gateways).
  verifyTls: false,
  alarmNameFallback: 'Threat Detected',
};

const alarmName = body?.name || alarm.name || body?.alarm_name || config.alarmNameFallback;
const alarmTs = body?.timestamp || body?.['@timestamp'] || null;

return [{
  json: {
    ...config,
    alarmName,
    alarmTs,
    alertKey: first.alert_key || null,
    siteId: scope.site_id || null,
    request: $input.first().json,
  },
}];

const res = $input.first().json;
const cookie = [].concat(res.headers?.['set-cookie'] ?? []).map((c) => c.split(';')[0]).join('; ');
if (!cookie) throw new Error('UniFi login did not return a session cookie');
return [{
  json: {
    cookie,
    csrf: res.headers?.['x-csrf-token'] ?? '',
    apiKey: '',
  },
}];

const cfg = $('Config').first().json;
if (!cfg.apiKey) throw new Error('apiKey is empty; set Config.apiKey or use UniFi login credentials');
return [{ json: { cookie: '', csrf: '', apiKey: cfg.apiKey } }];

const cfg = $('Config').first().json;
const session = $('Session').first().json;
const headers = { Accept: 'application/json', 'Content-Type': 'application/json' };
if (session.apiKey) headers['X-API-KEY'] = session.apiKey;
if (session.cookie) {
  headers.Cookie = session.cookie;
  if (session.csrf) headers['X-CSRF-Token'] = session.csrf;
}
const now = Date.now();
const body = {
  timestampFrom: now - cfg.lookbackMinutes * 60000,
  timestampTo: now,
  pageSize: 100,
  pageNumber: 0,
  threatTypes: ['THREAT', 'HONEYPOT'],
};
const url = cfg.gatewayUrl + '/proxy/network/v2/api/site/' + cfg.site + '/system-log/threat-alert';
const payload = await this.helpers.httpRequest({
  method: 'POST',
  url,
  headers,
  body,
  json: true,
  skipSslCertificateValidation: !cfg.verifyTls,
});
return [{ json: payload ?? {} }];

const state = $getWorkflowStaticData('global');
const now = Date.now();
state.seen = Object.fromEntries(Object.entries(state.seen ?? {}).filter(([, at]) => now - at < 86400000));

const entries = $input.all().flatMap(({ json }) => json.data ?? json.items ?? (json.id ? [json] : []));
const ids = [...new Set(entries.map((e) => e.parameters?.THREAT_LOG_ID?.id ?? e.id).filter(Boolean))]
  .filter((id) => !state.seen[id]);
for (const id of ids) state.seen[id] = now;
return ids.map((id) => ({ json: { id } }));

const cfg = $('Config').first().json;
const session = $('Session').first().json;
const threatId = $json.id;
const headers = { Accept: 'application/json' };
if (session.apiKey) headers['X-API-KEY'] = session.apiKey;
if (session.cookie) {
  headers.Cookie = session.cookie;
  if (session.csrf) headers['X-CSRF-Token'] = session.csrf;
}
const url = cfg.gatewayUrl + '/proxy/network/v2/api/site/' + cfg.site + '/inspection-logs/threats/' + threatId;
const payload = await this.helpers.httpRequest({
  method: 'GET',
  url,
  headers,
  json: true,
  skipSslCertificateValidation: !cfg.verifyTls,
});
return [{ json: payload ?? {} }];

const cfg = $('Config').first().json;
const state = $getWorkflowStaticData('global');
const now = Date.now();
// Muted signatures (expiry timestamps). v1 has no Slack mute UI; filter still honors static data.
state.muted = Object.fromEntries(Object.entries(state.muted ?? {}).filter(([, until]) => until > now));

const threats = $input.all()
  .map(({ json }) => (Array.isArray(json.data) ? json.data[0] : json.data) ?? json)
  .filter((t) => t?.signature && !state.muted[t.signature]);
if (!threats.length) return [];

const tally = (key) => {
  const groups = new Map();
  for (const t of threats) {
    const k = key(t);
    if (!k) continue;
    const g = groups.get(k) ?? { key: k, count: 0, t };
    g.count += 1;
    groups.set(k, g);
  }
  return [...groups.values()].sort((a, b) => b.count - a.count);
};
const tick = '\x60';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const top = (groups, line) => {
  const lines = groups.slice(0, 5).map(line);
  if (groups.length > 5) lines.push('_+' + (groups.length - 5) + ' more_');
  return lines.length ? lines.join('\n') : '_none_';
};
const fmtTs = (ms) => {
  if (ms == null || ms === '') return '—';
  let value = Number(ms);
  if (!Number.isFinite(value)) return '—';
  if (value > 1e12) value /= 1000;
  try {
    return new Date(value * 1000).toISOString().replace('T', ' ').replace(/\.\d+Z$/, ' UTC');
  } catch {
    return '—';
  }
};

const signatures = tally((t) => t.signature);
const sources = tally((t) => t.server_ip);
const clients = tally((t) => t.client_mac);
const risks = ['high', 'medium', 'low'];
const highest = risks.find((r) => threats.some((t) => t.risk === r)) ?? 'unknown';
const dot = { high: ':red_circle:', medium: ':large_orange_circle:', low: ':large_yellow_circle:' }[highest] ?? ':white_circle:';
const blocked = threats.filter((t) => t.action === 'blocked').length;
const plural = threats.length === 1 ? '' : 's';
const text = threats.length + ' threat' + plural + ' in the last ' + cfg.lookbackMinutes + ' min (highest risk: ' + highest + ')';
const gatewayLink = '<' + cfg.gatewayUrl + '|Open UniFi>';
const siteLine = 'site ' + tick + esc(cfg.site) + tick;
const when = fmtTs(cfg.alarmTs);

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: threats.length + ' threat' + plural + ' in the last ' + cfg.lookbackMinutes + ' min' },
  },
  {
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: (
        dot + ' Highest risk *' + esc(highest) + '*  |  '
        + 'Blocked ' + blocked + '/' + threats.length + '  |  '
        + esc(cfg.alarmName) + '  |  ' + siteLine + '  |  ' + when + '  |  ' + gatewayLink
      ),
    }],
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Signatures*\n' + top(signatures, (g) => (
        '• *' + g.count + '×* ' + esc(g.t.signature)
        + ' _(' + esc(g.t.risk) + ', ' + esc(g.t.signature_type || g.t.category || 'threat') + ')_'
      )),
    },
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Sources*\n' + top(sources, (g) => (
        '• *' + g.count + '×* ' + tick + esc(g.key) + tick + ' '
        + esc(g.t.counterpart_location || g.t.counterpart_country_code || '')
        + ' · ' + esc(g.t.threat_direction || g.t.direction || '')
        + ' · ' + esc(g.t.action || '')
      )),
    },
  },
];

if (clients.length) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Clients*\n' + top(clients, (g) => (
        '• *' + g.count + '×* ' + esc(g.t.client_name || 'unknown') + ' ' + tick + esc(g.key) + tick
      )),
    },
  });
}

const sample = threats[0];
const extras = [];
const proto = sample.protocol || sample.app_proto;
if (proto) extras.push('*Protocol:* ' + esc(proto));
const dst = sample.dest_port || sample.dst_port;
if (dst) extras.push('*Port:* ' + tick + esc(dst) + tick);
const host = sample.host || sample.hostname;
if (host) extras.push('*Host:* ' + tick + esc(host) + tick);
if (extras.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: extras.join(' · ') } });
}

return [{
  json: {
    text,
    blocks,
    unfurl_links: false,
    slackWebhookUrl: cfg.slackWebhookUrl,
  },
}];
